steps.script:
var sb = GameState.state.units["U_BEAST_SNAGGA_BOYZ_B"]
for k in ["moved", "advanced", "fell_back", "remained_stationary", "has_shot", "cannot_charge", "move_cap_inches"]:
	sb.flags.erase(k)
var i = 0
for m in sb.models:
	m["position"] = {"x": 1350.0 + (i % 5) * 60.0, "y": 600.0 + int(i / 5) * 60.0}
	m["alive"] = i < 9
	i += 1
var cg = GameState.state.units["U_CUSTODIAN_GUARD_B"]
i = 0
for m in cg.models:
	m["position"] = {"x": 580.0 + i * 73.0, "y": 630.0}
	i += 1
var dread = GameState.state.units["U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H"]
dread.models[0]["position"] = {"x": 1600.0, "y": 2250.0}
var wb = GameState.state.units["U_WARBOSS_IN_MEGA_ARMOUR_A"]
wb.models[0]["position"] = {"x": 150.0, "y": 2300.0}
wb.flags["moved"] = true
tree.root.get_node("Main")._recreate_unit_visuals()
var edge = AIDecisionMaker._get_closest_model_distance_inches(sb, cg)
var cen = AIDecisionMaker._get_unit_centroid(sb).distance_to(AIDecisionMaker._get_unit_centroid(cg)) / 40.0
return "edge=%.1f centroid=%.1f" % [edge, cen]

var rich = tree.root.get_node("Main")._ai_suggestion_panel._rich
var t = rich.get_parsed_text()
var at = t.find("Charge intent")
if at < 0:
	return -1
var para = t.substr(0, at).count("\n")
rich.scroll_to_paragraph(maxi(para - 3, 0))
return para
